'use strict';

// MODULES //

var logger = require( 'debug' );
var hash = require( './hash.js' );


// VARIABLES //

var debug = logger( 'markdown-to-semantic-document:provenance' );


// FUNCTIONS //

/**
* Creates an index of MDAST nodes and traversal paths.
*
* @private
* @param {Object} node - MDAST node
* @param {Array} path - traversal path
* @param {Array} nodes - nodes
* @param {Array} paths - paths
* @returns {void}
*/
function index( node, path, nodes, paths ) {
	var i;

	// Store nodes and paths at matching indexes. MDAST nodes do not provide parent pointers, so this table supplies stable document-local traversal identities...
	nodes.push( node );
	paths.push( path );
	if ( node.children ) {
		for ( i = 0; i < node.children.length; i++ ) {
			index( node.children[ i ], path.concat( i ), nodes, paths );
		}
	}
}

/**
* Clones an MDAST position.
*
* @private
* @param {Object} position - MDAST position
* @returns {Object} cloned position
*/
function clonePosition( position ) {
	return {
		'start': {
			'line': position.start.line,
			'column': position.start.column,
			'offset': position.start.offset
		},
		'end': {
			'line': position.end.line,
			'column': position.end.column,
			'offset': position.end.offset
		}
	};
}

/**
* Returns an exact source slice for an MDAST node.
*
* @private
* @param {Object} node - MDAST node
* @param {string} source - source Markdown
* @returns {string} source slice
*/
function slice( node, source ) {
	// Some synthesized/plugin nodes may lack offsets. Return an empty slice rather than guessing from line/column data, which would compromise exact hashes...
	if (
		!node.position ||
		node.position.start.offset === void 0 ||
		node.position.end.offset === void 0
	) {
		debug( 'Unable to slice source node without offsets: type=%s', node.type );
		return '';
	}
	return source.slice( node.position.start.offset, node.position.end.offset );
}


// MAIN //

/**
* Returns provenance helpers for an MDAST tree.
*
* @private
* @param {Object} tree - MDAST tree
* @param {string} source - source Markdown
* @param {Options} options - conversion options
* @returns {Object} provenance helpers
*/
function provenance( tree, source, options ) {
	var paths = [];
	var nodes = [];

	debug( 'Indexing MDAST provenance: sourceLength=%d includePositions=%s includeSourceSlices=%s', source.length, options.includePositions, options.includeSourceSlices );

	// Build the lookup once. Every subsequent accounting and semantic-node call can then derive paths without repeatedly traversing the source tree:
	index( tree, [], nodes, paths );
	debug( 'Indexed MDAST provenance: nodes=%d', nodes.length );

	return {
		'path': path,
		'source': createSource,
		'sourceHash': sourceHash,
		'slice': sourceSlice
	};

	/**
	* Returns the traversal path for an MDAST node.
	*
	* @private
	* @param {Object} node - MDAST node
	* @returns {Array} traversal path
	*/
	function path( node ) {
		var idx = nodes.indexOf( node );

		// Return a copy so consumers cannot mutate the indexed canonical path:
		return ( idx === -1 ) ? [] : paths[ idx ].slice();
	}

	/**
	* Returns a semantic source object.
	*
	* @private
	* @param {Array} mdast - MDAST nodes
	* @param {string} [transformation] - transformation name
	* @returns {Object} source object
	*/
	function createSource( mdast, transformation ) {
		var envelope;
		var range;
		var refs;
		var node;
		var ref;
		var i;

		refs = [];

		// A semantic node may combine several source nodes (for example, a section wrapper and its end marker). Preserve an ordered reference for each one...
		for ( i = 0; i < mdast.length; i++ ) {
			node = mdast[ i ];
			ref = {
				'astPath': path( node ),
				'origin': ( transformation ) ? 'transformed' : 'source',
				'transformation': transformation || null,
				'sourceHash': hash( slice( node, source ) )
			};
			if ( options.includePositions && node.position ) {
				// The envelope spans every contributing node and supports convenient UI navigation without losing the more precise individual ranges...
				range = clonePosition( node.position );
				ref.range = range;
				if ( envelope ) {
					if ( range.start.offset < envelope.start.offset ) {
						envelope.start = range.start;
					}
					if ( range.end.offset > envelope.end.offset ) {
						envelope.end = range.end;
					}
				} else {
					envelope = clonePosition( node.position );
				}
			}
			if ( options.includeSourceSlices ) {
				// Source slices are opt-in because they can substantially increase output size and may duplicate user-authored content:
				ref.value = slice( node, source );
			}
			refs.push( ref );
		}
		ref = {
			'refs': refs
		};
		if ( envelope ) {
			ref.envelope = envelope;
		}
		return ref;
	}

	/**
	* Returns an aggregate source hash for MDAST nodes.
	*
	* @private
	* @param {Array} mdast - MDAST nodes
	* @returns {string} source hash
	*/
	function sourceHash( mdast ) {
		var values = [];
		var i;

		// A single-node hash must equal the hash on its source reference and accounting record. Multi-node values hash an ordered array to retain bounds...
		if ( mdast.length === 1 ) {
			return hash( slice( mdast[ 0 ], source ) );
		}
		for ( i = 0; i < mdast.length; i++ ) {
			values.push( slice( mdast[ i ], source ) );
		}
		return hash( values );
	}

	/**
	* Returns an exact source slice.
	*
	* @private
	* @param {Object} node - MDAST node
	* @returns {string} source slice
	*/
	function sourceSlice( node ) {
		return slice( node, source );
	}
}


// EXPORTS //

module.exports = provenance;
